```tsx
import { useId } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({ title, message, actionLabel, onAction }: EmptyStateProps) {
  const headingId = useId();

  return (
    <section className="empty-state" aria-labelledby={headingId}>
      <h2 id={headingId} className="empty-state__title">
        {title}
      </h2>
      <p className="empty-state__message">{message}</p>
      <button type="button" className="empty-state__action" onClick={onAction}>
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  box-sizing: border-box;
  width: 100%;
  min-height: 100%;
  padding: 2rem;
  text-align: center;
  color: var(--ink);
  background: transparent;
}

.empty-state__title {
  margin: 0;
  font-size: clamp(1.25rem, 2.5vw + 0.5rem, 2rem);
  font-weight: 600;
  line-height: 1.2;
  color: var(--ink);
}

.empty-state__message {
  margin: 0;
  max-width: 36ch;
  font-size: clamp(0.95rem, 1vw + 0.5rem, 1.125rem);
  line-height: 1.5;
  color: var(--ink);
}

.empty-state__action {
  margin-top: 0.5rem;
  padding: 0.7em 1.4em;
  font: inherit;
  font-size: clamp(0.95rem, 1vw + 0.5rem, 1.125rem);
  font-weight: 600;
  border: 0;
  border-radius: 999px;
  background: var(--myelin);
  color: var(--slide);
  cursor: pointer;
}

.empty-state__action:hover {
  text-decoration: underline;
  text-underline-offset: 0.2em;
}
```

